<?php
declare(strict_types=1);$config=require __DIR__.'/../config/config.php';require_once __DIR__.'/../app/Database.php';require_once __DIR__.'/../app/Auth.php';require_once __DIR__.'/../app/UserStorage.php';require_once __DIR__.'/../app/WorkspaceService.php';try{$user=(new Auth($config))->requireUser();$config['workspace']=UserStorage::home($config,(int)$user['id']);$ws=new WorkspaceService($config);$path=(string)($_GET['path']??'arquivos');$action=(string)($_GET['action']??'list');$safe=$ws->safe($path,true);if($action==='read'){if(!is_file($safe)||filesize($safe)>2*1024*1024)throw new RuntimeException('Arquivo inexistente ou grande demais.');$content=file_get_contents($safe);if($content===false||preg_match('//u',$content)!==1)throw new RuntimeException('Arquivo binário ou inválido.');json_response(['ok'=>true,'path'=>$path,'content'=>$content]);}if($action==='download'){if(!is_file($safe))throw new RuntimeException('Arquivo inexistente.');header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.basename($safe).'"');readfile($safe);exit;}json_response(['ok'=>true,'path'=>$path,'items'=>$ws->list($path)]);}catch(Throwable $e){json_response(['ok'=>false,'error'=>$e->getMessage()],400);}
?>
